/**
 * Main Application Component
 *
 * Manages the discovery flow, continuous block results, visual hall inspection,
 * and the step-by-step booking/reservation assistant.
 */
import React, { useState } from 'react';
import { SearchForm } from './components/SearchForm';
import { ResultsGrid } from './components/ResultsGrid';
import { LoadingState } from './components/LoadingState';
import { BookingModal } from './components/BookingModal';
import { SeatMapInspector } from './components/SeatMapInspector';
import { AutoBookedView } from './components/AutoBookedView';
import type { RankedResult } from '../background/service-worker';

type ViewState = 'search' | 'loading' | 'results' | 'auto_booked' | 'error';

interface SearchParams {
  movie: string;
  seats: number;
}

interface AutoBookedPayload {
  result: RankedResult;
  optimalSeatLabels: string[];
  bookingUrl: string;
  tabId?: number;
}

export default function App() {
  const [view, setView] = useState<ViewState>('search');
  const [results, setResults] = useState<RankedResult[]>([]);
  const [lastSearch, setLastSearch] = useState<SearchParams>({ movie: '', seats: 2 });
  const [errorMessage, setErrorMessage] = useState<string>('');
  const [autoBookedData, setAutoBookedData] = useState<AutoBookedPayload | null>(null);

  // Modals
  const [selectedForBooking, setSelectedForBooking] = useState<RankedResult | null>(null);
  const [inspectingResult, setInspectingResult] = useState<RankedResult | null>(null);

  /**
   * Helper to send messages with timeout and runtime.lastError safety
   */
  const sendMessageWithTimeout = <T,>(message: any, timeoutMs = 15000): Promise<T> => {
    return new Promise((resolve, reject) => {
      let resolved = false;
      const timer = setTimeout(() => {
        if (!resolved) {
          resolved = true;
          reject(new Error('Discovery timed out. Please check your network connection and try again.'));
        }
      }, timeoutMs);

      try {
        chrome.runtime.sendMessage(message, (response: T) => {
          if (resolved) return;
          resolved = true;
          clearTimeout(timer);
          if (chrome.runtime.lastError) {
            reject(new Error(chrome.runtime.lastError.message));
          } else {
            resolve(response);
          }
        });
      } catch (err) {
        if (!resolved) {
          resolved = true;
          clearTimeout(timer);
          reject(err);
        }
      }
    });
  };

  /**
   * Send discovery request to service worker and auto-reserve first found block
   */
  const runDiscovery = async (params: SearchParams) => {
    setLastSearch(params);
    setErrorMessage('');
    setAutoBookedData(null);
    setView('loading');
    setSelectedForBooking(null);
    setInspectingResult(null);

    try {
      const response = await sendMessageWithTimeout<any>({
        type: 'DISCOVER',
        request: {
          movieName: params.movie,
          requiredSeats: params.seats,
          criteria: {},
        },
      }, 15000);

      if (response?.results && response.results.length > 0) {
        setResults(response.results);
        const topResult = response.results[0];

        // Automatic "First found, first select" flow:
        // Automatically reserve the optimal continuous seats from the first available block
        // and navigate straight to the checkout/payment page!
        try {
          const reserveRes = await sendMessageWithTimeout<any>({
            type: 'RECHECK_AND_RESERVE',
            payload: {
              showtime: topResult.showtime,
              seatBlock: topResult.seatBlock,
              requiredSeats: params.seats,
            },
          }, 12000);

          if (reserveRes?.success) {
            setAutoBookedData({
              result: topResult,
              optimalSeatLabels: reserveRes.seatLabels || [],
              bookingUrl: reserveRes.bookingUrl || topResult.showtime.bookingUrl,
              tabId: reserveRes.tabId,
            });
            setView('auto_booked');
            return;
          }
        } catch (reserveErr) {
          console.warn('Auto-reserve step error, falling back to results list:', reserveErr);
        }

        // Fallback to manual selection list if auto-reservation encountered an issue
        setView('results');
      } else {
        setResults([]);
        const errorDetail = response?.errors?.length
          ? response.errors.map((e: any) => e.error).join('; ')
          : `No continuous seat blocks of ${params.seats} seat${params.seats > 1 ? 's' : ''} found for "${params.movie}".`;
        setErrorMessage(errorDetail);
        setView('error');
      }
    } catch (error) {
      console.error('Discovery failed:', error);
      setResults([]);
      setErrorMessage((error as Error)?.message || 'An unexpected error occurred during discovery.');
      setView('error');
    }
  };

  const reset = () => {
    setSelectedForBooking(null);
    setInspectingResult(null);
    setAutoBookedData(null);
    setErrorMessage('');
    setView('search');
  };

  return (
    <div className="app">
      <header className="app-header">
        <h1>🎬 Movie Tickets</h1>
        <p className="tagline">Find the best continuous seats in seconds</p>
      </header>

      <main>
        {view === 'loading' && (
          <LoadingState
            movie={lastSearch.movie}
            seats={lastSearch.seats}
            onCancel={reset}
          />
        )}

        {view === 'error' && (
          <div className="error-state">
            <p className="error-message">
              {errorMessage || `No continuous seat blocks found for "${lastSearch.movie}".`}
            </p>
            <p className="error-hint">Try searching for fewer seats, another movie title, or browse available shows.</p>
            <button className="primary" onClick={reset}>← Try again</button>
          </div>
        )}

        {view === 'auto_booked' && autoBookedData && (
          <AutoBookedView
            result={autoBookedData.result}
            requiredSeats={lastSearch.seats}
            optimalSeatLabels={autoBookedData.optimalSeatLabels}
            bookingUrl={autoBookedData.bookingUrl}
            tabId={autoBookedData.tabId}
            totalOptionsCount={results.length}
            onViewAllOptions={() => setView('results')}
            onNewSearch={reset}
          />
        )}

        {view === 'results' && (
          <ResultsGrid
            results={results}
            requiredSeats={lastSearch.seats}
            onBack={reset}
            onSelectResult={res => setSelectedForBooking(res)}
            onInspectResult={res => setInspectingResult(res)}
          />
        )}

        {view === 'search' && (
          <SearchForm
            onSubmit={runDiscovery}
            initialMovie={lastSearch.movie}
            initialSeats={lastSearch.seats}
          />
        )}
      </main>

      {/* Visual Hall Inspector Modal */}
      {inspectingResult && (
        <SeatMapInspector
          result={inspectingResult}
          requiredSeats={lastSearch.seats}
          onClose={() => setInspectingResult(null)}
          onBook={() => {
            const target = inspectingResult;
            setInspectingResult(null);
            setSelectedForBooking(target);
          }}
        />
      )}

      {/* Automated Booking & Reservation Assistant Modal */}
      {selectedForBooking && (
        <BookingModal
          result={selectedForBooking}
          requiredSeats={lastSearch.seats}
          onClose={() => setSelectedForBooking(null)}
          onNewSearch={reset}
        />
      )}

      <footer className="app-footer">
        <span>Instant continuous blocks • Star Cineplex Bangladesh integration</span>
      </footer>
    </div>
  );
}